    max_value                            BIGINT        NOT NULL,
    is_active                            BOOLEAN       NOT NULL DEFAULT TRUE,
    monthly_cost                         NUMERIC(18,2) NOT NULL,
    currency                             CHAR(3)       NOT NULL DEFAULT 'USD',
    billing_cycle                        CHAR(1)       NOT NULL DEFAULT 'M',
    term_count                           INTEGER       NOT NULL DEFAULT 1,
    term_type                            CHAR(1)       NOT NULL DEFAULT 'M',
    description                          VARCHAR(255) ,
    CONSTRAINT subscription_addon_pk PRIMARY KEY (id)
);

-- Single-use, TTL-bounded nonces (OAuth connect-state, JWT handoff). Natural key, no sequence.
CREATE TABLE IF NOT EXISTS auth_nonce (
    nonce                                VARCHAR(64)   NOT NULL,
    purpose                              VARCHAR(20)   NOT NULL,
    payload                              TEXT          NOT NULL,
    created_at                           TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT auth_nonce_pk PRIMARY KEY (nonce)
);

-- Active plan subscriptions per business partner
CREATE TABLE IF NOT EXISTS partner_plan_subscription (
    partner_id                           BIGINT        NOT NULL,
    plan_id                              VARCHAR(20)   NOT NULL,
    begda                                TIMESTAMP     NOT NULL,
    endda                                TIMESTAMP    ,
    monthly_cost                         NUMERIC(18,2) NOT NULL,
    currency                             CHAR(3)       NOT NULL,
    status                               CHAR(1)       NOT NULL,
    auto_renew                           BOOLEAN       NOT NULL DEFAULT TRUE,
    provider_subscription_id             VARCHAR(64)  ,
    billing_cycle                        CHAR(1)      ,
    term_count                           INTEGER      ,
    term_type                            CHAR(1)      ,
    amount_minor                         BIGINT       ,
    renewal_date                         TIMESTAMP    ,
    next_charge_date                     TIMESTAMP    ,
    cancelled_at                         TIMESTAMP    ,
    effective_cancel_date                TIMESTAMP    ,
    trial_end                            TIMESTAMP    ,
    seats                                INTEGER      ,
    CONSTRAINT partner_plan_subscription_pk PRIMARY KEY (partner_id, plan_id, begda)
);
CREATE INDEX IF NOT EXISTS idx_partner_plan_subscription_provider_sub ON partner_plan_subscription(provider_subscription_id);

-- Active add-on subscriptions per business partner
CREATE TABLE IF NOT EXISTS partner_addon_subscription (
    partner_id                           BIGINT        NOT NULL,
    addon_id                             VARCHAR(20)   NOT NULL,
    auto_increase                        BOOLEAN       NOT NULL DEFAULT FALSE,
    begda                                TIMESTAMP     NOT NULL,
    endda                                TIMESTAMP    ,
    monthly_cost                         NUMERIC(18,2) NOT NULL,
    currency                             CHAR(3)       NOT NULL,
    status                               CHAR(1)       NOT NULL,
    auto_renew                           BOOLEAN       NOT NULL DEFAULT TRUE,
    billing_cycle                        CHAR(1)      ,
    term_count                           INTEGER      ,
    term_type                            CHAR(1)      ,
    amount_minor                         BIGINT       ,
    renewal_date                         TIMESTAMP    ,
    next_charge_date                     TIMESTAMP    ,
    CONSTRAINT partner_addon_subscription_pk PRIMARY KEY (partner_id, addon_id, begda)
);

-- Resource usage tracking for quota enforcement
CREATE TABLE IF NOT EXISTS usage_ledger (
    partner_id                           BIGINT        NOT NULL,
    usage_time                           TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    resource_name                        VARCHAR(50)   NOT NULL,
    amount                               BIGINT        NOT NULL,
    notes                                VARCHAR(255) ,
    CONSTRAINT usage_ledger_pk PRIMARY KEY (partner_id, usage_time)
);
CREATE INDEX IF NOT EXISTS idx_usage_ledger_quota ON usage_ledger(partner_id, resource_name, usage_time);

-- Raw inbound payment provider webhooks — idempotency + audit
CREATE TABLE IF NOT EXISTS payment_webhook_log (
    id                                   BIGINT        NOT NULL,
    provider                             VARCHAR(30)   NOT NULL,
    event_id                             VARCHAR(255)  NOT NULL,
    event_type                           VARCHAR(100)  NOT NULL,
    processing_status                    CHAR(1)       NOT NULL DEFAULT 'R',
    error_message                        TEXT         ,
    request_id                           TEXT         ,
    raw_payload                          TEXT         ,
    replay_attempts                      INTEGER       NOT NULL DEFAULT 0,
    received_at                          TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    processed_at                         TIMESTAMP    ,
    last_claimed_at                      TIMESTAMP    ,
    CONSTRAINT payment_webhook_log_pk PRIMARY KEY (id),
    CONSTRAINT chk_payment_webhook_status CHECK (processing_status IN ('R', 'P', 'F', 'D', 'S', 'L')),
    CONSTRAINT chk_payment_webhook_replay_attempts CHECK (replay_attempts >= 0)
);
CREATE UNIQUE INDEX IF NOT EXISTS payment_webhook_log_uq ON payment_webhook_log(provider, event_id);
CREATE INDEX IF NOT EXISTS idx_payment_webhook_replay ON payment_webhook_log(processing_status, id);

CREATE SEQUENCE IF NOT EXISTS payment_webhook_log_seq INCREMENT BY 1 START WITH 1;
INSERT INTO table_sequence_usage (table_name, column_name, sequence_name) VALUES ('payment_webhook_log', 'id', 'payment_webhook_log_seq') ON CONFLICT DO NOTHING;

-- Stored payment methods per business partner (provider customer tokens)
CREATE TABLE IF NOT EXISTS payment_method (
    id                                   BIGINT        NOT NULL,
    partner_id                           BIGINT        NOT NULL,
    provider                             VARCHAR(30)   NOT NULL,
    provider_token                       VARCHAR(255)  NOT NULL,
    method_type                          VARCHAR(20)   NOT NULL,
    is_default                           BOOLEAN       NOT NULL DEFAULT FALSE,
    created_at                           TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT payment_method_pk PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS idx_payment_method_default ON payment_method(partner_id, is_default);

CREATE SEQUENCE IF NOT EXISTS payment_method_seq INCREMENT BY 1 START WITH 1;
INSERT INTO table_sequence_usage (table_name, column_name, sequence_name) VALUES ('payment_method', 'id', 'payment_method_seq') ON CONFLICT DO NOTHING;

-- Versioned (user, partner) bank account details for out-bound payouts.
-- Owned by keel/payout. Raw routing details live with the provider
-- (Airwallex / Stripe Connect / Wise); this row carries only the
-- provider handle plus tax/correspondence metadata.
-- Rows are versions: identity-bearing changes (provider, account,
-- tax id, holder, country, currency, address) close the active row
-- (status='S', superseded_at) and insert a new one; onboarding
-- lifecycle fields mutate the active row in place. At most one
-- active row per (user_id, partner_id) — partial unique index on
-- PostgreSQL, service-enforced on MySQL.
CREATE TABLE IF NOT EXISTS user_bank_info (
    id                                   BIGINT        NOT NULL,
    user_id                              BIGINT        NOT NULL,
    partner_id                           BIGINT        NOT NULL,
    country_code                         CHAR(2)       NOT NULL,
    currency                             CHAR(3)       NOT NULL,
    account_holder_name                  VARCHAR(200)  NOT NULL,
    billing_address                      TEXT          NOT NULL,
    tax_id_type                          CHAR(1)       NOT NULL,
    tax_id_encrypted                     BYTEA         NOT NULL,
    provider                             CHAR(2)       NOT NULL,
    provider_account_id                  VARCHAR(100) ,
    provider_agreement                   BOOLEAN       NOT NULL DEFAULT FALSE,
    provider_onboarded_at                TIMESTAMP    ,
    status                               CHAR(1)       NOT NULL DEFAULT 'A',
    superseded_at                        TIMESTAMP    ,
    created_at                           TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at                           TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT user_bank_info_pk PRIMARY KEY (id),
    CONSTRAINT chk_user_bank_info_lifecycle CHECK ((status = 'A' AND superseded_at IS NULL) OR (status = 'S' AND superseded_at IS NOT NULL))
);
CREATE UNIQUE INDEX IF NOT EXISTS user_bank_info_active_uq ON user_bank_info(user_id, partner_id) WHERE status = 'A';
CREATE UNIQUE INDEX IF NOT EXISTS user_bank_info_id_partner_uq ON user_bank_info(id, partner_id);
CREATE INDEX IF NOT EXISTS idx_user_bank_info_partner ON user_bank_info(partner_id);

CREATE SEQUENCE IF NOT EXISTS user_bank_info_seq INCREMENT BY 1 START WITH 1;
INSERT INTO table_sequence_usage (table_name, column_name, sequence_name) VALUES ('user_bank_info', 'id', 'user_bank_info_seq') ON CONFLICT DO NOTHING;

-- Saved payment methods for end users (cards, wallets, bank accounts).
-- Distinct from `payment_method`, which is partner-scoped for SaaS
-- billing — this row is per (user_id), the consumer cards a user has
-- on file for in-bound payments. provider_token is the provider's
-- reusable handle (Stripe PaymentMethod id, SetupIntent id, etc.);
-- raw card numbers / IBANs / SWIFT never land here.
CREATE TABLE IF NOT EXISTS user_payment_method (
    id                                   BIGINT        NOT NULL,
    user_id                              BIGINT        NOT NULL,
    method_type                          VARCHAR(20)   NOT NULL,
    provider                             VARCHAR(30)   NOT NULL,
    provider_token                       VARCHAR(255)  NOT NULL,
    last_four                            VARCHAR(4)   ,
    brand                                VARCHAR(20)  ,
    expiry_month                         SMALLINT     ,
    expiry_year                          SMALLINT     ,
    currency                             CHAR(3)       NOT NULL DEFAULT 'USD',
    is_default                           BOOLEAN       NOT NULL DEFAULT FALSE,
    created_at                           TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT user_payment_method_pk PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS idx_user_payment_method_user ON user_payment_method(user_id, is_default);

CREATE SEQUENCE IF NOT EXISTS user_payment_method_seq INCREMENT BY 1 START WITH 1;
INSERT INTO table_sequence_usage (table_name, column_name, sequence_name) VALUES ('user_payment_method', 'id', 'user_payment_method_seq') ON CONFLICT DO NOTHING;

-- Per-table custom actions surfaced as buttons in CRUD UIs. Each row
-- registers ONE action; the downstream application must also (a) seed
-- the matching authorization_object + authorization_object_action rows
-- so roles can grant access, and (b) register an HTTP handler at the
-- conventional URL POST /<rest_prefix>/<table_name>/<action_name>.
-- 
-- authorization_object.id mirrors the uppercased table name and
-- authorization_object_action.action mirrors the uppercased action_name
-- — gives each table its own action namespace so the same action name
-- ('assign', 'enable', 'calculate') can mean different things on
-- different tables without a shared auth dimension.
-- 
-- record_specific=TRUE  → button renders next to per-row edit/delete.
-- record_specific=FALSE → button renders next to the "New Record"
--                         control at the table-level toolbar.
-- 
-- Reserved action_name values that collide with generic CRUD subpaths
-- (list / get / post / delete / get-paginated) are rejected at REST
-- service boot.
CREATE TABLE IF NOT EXISTS table_action (
    table_name                           VARCHAR(80)   NOT NULL,
    action_name                          VARCHAR(30)   NOT NULL,
    caption                              VARCHAR(80)   NOT NULL,
    icon                                 VARCHAR(40)  ,
    record_specific                      BOOLEAN       NOT NULL DEFAULT FALSE,
    action_kind                          CHAR(1)       NOT NULL DEFAULT 'P',
    method_name                          VARCHAR(80)  ,
    display_order                        SMALLINT      NOT NULL DEFAULT 10,
    confirm_message                      VARCHAR(200) ,
    CONSTRAINT table_action_pk PRIMARY KEY (table_name, action_name)
);
CREATE INDEX IF NOT EXISTS idx_table_action_table ON table_action(table_name);

-- Billing invoices per partner (provider-issued or self-scheduled)
CREATE TABLE IF NOT EXISTS invoice (
    id                                   BIGINT        NOT NULL,
    partner_id                           BIGINT        NOT NULL,
    invoice_number                       VARCHAR(30)   NOT NULL,
    status                               CHAR(1)       NOT NULL DEFAULT 'D',
    subtotal                             NUMERIC(20,4) NOT NULL,
    tax                                  NUMERIC(20,4) NOT NULL DEFAULT 0.00,
    total                                NUMERIC(20,4) NOT NULL,
    total_minor                          BIGINT        NOT NULL,
    currency                             CHAR(3)       NOT NULL DEFAULT 'USD',
    issued_at                            TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    due_at                               TIMESTAMP    ,
    paid_at                              TIMESTAMP    ,
    pdf_storage_path                     VARCHAR(500) ,
    provider_invoice_id                  VARCHAR(255) ,
    provider_charge_id                   VARCHAR(255) ,
    attempt_count                        INTEGER       NOT NULL DEFAULT 0,
    next_attempt_at                      TIMESTAMP    ,
    last_error                           TEXT         ,
    CONSTRAINT invoice_pk PRIMARY KEY (id)
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_invoice_number ON invoice(invoice_number);
CREATE INDEX IF NOT EXISTS idx_invoice_partner ON invoice(partner_id);
CREATE UNIQUE INDEX IF NOT EXISTS invoice_id_partner_uq ON invoice(id, partner_id);
CREATE UNIQUE INDEX IF NOT EXISTS invoice_id_currency_uq ON invoice(id, currency);

CREATE SEQUENCE IF NOT EXISTS invoice_seq INCREMENT BY 1 START WITH 1;
INSERT INTO table_sequence_usage (table_name, column_name, sequence_name) VALUES ('invoice', 'id', 'invoice_seq') ON CONFLICT DO NOTHING;

-- Line items for an invoice — domain-neutral finance data only.
-- amount_minor is the authoritative integer minor-unit amount (amount
-- stays for display) and has NO default: writers must supply it.
-- service_from / service_to (inclusive / exclusive) bound the
-- covered-service period for period-scoped consumers (proration,
-- partial refunds). What a line sells lives in domain extension tables
-- (e.g. subscription_invoice_line), never here.
CREATE TABLE IF NOT EXISTS invoice_line (
    invoice_id                           BIGINT        NOT NULL,
    seq                                  INTEGER       NOT NULL,
    description                          VARCHAR(200)  NOT NULL,
    quantity                             INTEGER       NOT NULL DEFAULT 1,
    unit_price                           NUMERIC(20,4) NOT NULL,
    amount                               NUMERIC(20,4) NOT NULL,
    amount_minor                         BIGINT        NOT NULL,
    service_from                         TIMESTAMP    ,
    service_to                           TIMESTAMP    ,
    CONSTRAINT invoice_line_pk PRIMARY KEY (invoice_id, seq)
);

-- Partner ↔ provider-customer token, one row per (partner, provider). Its own
-- table (not a method_type='customer' row in payment_method) so payment_method
-- holds only real chargeable methods. Used for billing-portal sessions and
-- recurring-invoice attribution (the reverse token→partner lookup).
CREATE TABLE IF NOT EXISTS partner_billing_customer (
    partner_id                           BIGINT        NOT NULL,
    provider                             VARCHAR(30)   NOT NULL,
    customer_token                       VARCHAR(255)  NOT NULL,
    created_at                           TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT partner_billing_customer_pk PRIMARY KEY (partner_id, provider)
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_partner_billing_customer_token ON partner_billing_customer(provider, customer_token);

-- Subscription-domain extension of a generic invoice line: names the
-- plan or add-on the line bills. Exactly one of plan_id / addon_id is
-- set (check-enforced). Lines with no row here are non-subscription
-- charges (fees, adjustments). Keeps invoice / invoice_line
-- domain-neutral for finance purposes.
CREATE TABLE IF NOT EXISTS subscription_invoice_line (
    invoice_id                           BIGINT        NOT NULL,
    invoice_line_seq                     INTEGER       NOT NULL,
    plan_id                              VARCHAR(20)  ,
    addon_id                             VARCHAR(20)  ,
    CONSTRAINT subscription_invoice_line_pk PRIMARY KEY (invoice_id, invoice_line_seq),
    CONSTRAINT chk_sub_invoice_line_one_of CHECK ((plan_id IS NOT NULL AND addon_id IS NULL) OR (plan_id IS NULL AND addon_id IS NOT NULL))
);

-- Completed/failed/refunded payment transactions per partner —
-- domain-neutral finance data: a payment settles an invoice, whatever
-- the invoice sells. What was bought resolves through the invoice's
-- lines and their domain extension tables, never through columns here.
CREATE TABLE IF NOT EXISTS payment_record (
    id                                   BIGINT        NOT NULL,
    partner_id                           BIGINT       ,
    provider                             VARCHAR(30)   NOT NULL,
    provider_payment_id                  VARCHAR(255) ,
    provider_event_type                  VARCHAR(100) ,
    provider_charge_id                   VARCHAR(255) ,
    amount                               NUMERIC(20,4) NOT NULL,
    amount_minor                         BIGINT        NOT NULL,
    currency                             CHAR(3)       NOT NULL,
    invoice_id                           BIGINT       ,
    payment_status                       CHAR(1)       NOT NULL,
    paid_at                              TIMESTAMP    ,
    raw_payload                          TEXT         ,
    created_at                           TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT payment_record_pk PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS idx_payment_record_partner ON payment_record(partner_id, paid_at);
CREATE INDEX IF NOT EXISTS idx_payment_record_provider_charge ON payment_record(provider, provider_charge_id);
CREATE UNIQUE INDEX IF NOT EXISTS payment_record_provider_uq ON payment_record(provider, provider_payment_id) WHERE provider_payment_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS payment_record_id_invoice_uq ON payment_record(id, invoice_id);

CREATE SEQUENCE IF NOT EXISTS payment_record_seq INCREMENT BY 1 START WITH 1;
INSERT INTO table_sequence_usage (table_name, column_name, sequence_name) VALUES ('payment_record', 'id', 'payment_record_seq') ON CONFLICT DO NOTHING;

-- Durable allocation of one payment (or refund) to one invoice line in
-- integer minor units. entry_type P allocates a collected payment
-- (positive), R a refund (negative) — check-enforced. Currency is not
-- repeated here: it is authoritative on the referenced payment/invoice.
-- Consumers that recognize value per line (commission ledgers, revenue
-- reporting, partial-refund processing) key on this row rather than
-- reconstructing identity from payment + invoice + line columns.
CREATE TABLE IF NOT EXISTS invoice_line_payment (
    id                                   BIGINT        NOT NULL,
    payment_record_id                    BIGINT        NOT NULL,
    invoice_id                           BIGINT        NOT NULL,
    invoice_line_seq                     INTEGER       NOT NULL,
    entry_type                           CHAR(1)       NOT NULL DEFAULT 'P',
    amount_minor                         BIGINT        NOT NULL,
    provider_ref                         VARCHAR(255) ,
    created_at                           TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT invoice_line_payment_pk PRIMARY KEY (id),
    CONSTRAINT chk_inv_line_pmt_sign CHECK ((entry_type = 'P' AND amount_minor > 0) OR (entry_type = 'R' AND amount_minor < 0))
);
CREATE UNIQUE INDEX IF NOT EXISTS inv_line_pmt_ref_uq ON invoice_line_payment(provider_ref) WHERE provider_ref IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_inv_line_pmt_payment ON invoice_line_payment(payment_record_id);
CREATE INDEX IF NOT EXISTS idx_inv_line_pmt_line ON invoice_line_payment(invoice_id, invoice_line_seq);

CREATE SEQUENCE IF NOT EXISTS invoice_line_payment_seq INCREMENT BY 1 START WITH 1;
INSERT INTO table_sequence_usage (table_name, column_name, sequence_name) VALUES ('invoice_line_payment', 'id', 'invoice_line_payment_seq') ON CONFLICT DO NOTHING;

-- Raw inbound payout-provider webhooks — durable event-id idempotency +
-- audit for account-lifecycle and transfer-lifecycle events. Financial
-- events must never rely on a process-local or expiring cache; the
-- UNIQUE (provider, event_id) index is the authoritative race guard.
CREATE TABLE IF NOT EXISTS payout_webhook_log (
    id                                   BIGINT        NOT NULL,
    provider                             CHAR(2)       NOT NULL,
    event_id                             VARCHAR(255)  NOT NULL,
    event_type                           VARCHAR(100)  NOT NULL,
    provider_account_id                  VARCHAR(100) ,
    provider_transfer_id                 VARCHAR(255) ,
    processing_status                    CHAR(1)       NOT NULL DEFAULT 'R',
    error_message                        TEXT         ,
    raw_payload                          TEXT         ,
    received_at                          TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    processed_at                         TIMESTAMP    ,
    CONSTRAINT payout_webhook_log_pk PRIMARY KEY (id)
);
CREATE UNIQUE INDEX IF NOT EXISTS payout_webhook_log_uq ON payout_webhook_log(provider, event_id);
CREATE INDEX IF NOT EXISTS idx_payout_webhook_transfer ON payout_webhook_log(provider_transfer_id);

CREATE SEQUENCE IF NOT EXISTS payout_webhook_log_seq INCREMENT BY 1 START WITH 1;
INSERT INTO table_sequence_usage (table_name, column_name, sequence_name) VALUES ('payout_webhook_log', 'id', 'payout_webhook_log_seq') ON CONFLICT DO NOTHING;

-- Transactional outbox — events captured in the same tx as a domain write, then drained by a lease worker for reliable at-least-once delivery
CREATE TABLE IF NOT EXISTS outbox_event (
    id                                   BIGINT        NOT NULL,
    partner_id                           BIGINT       ,
    aggregate_type                       VARCHAR(64)   NOT NULL,
    aggregate_id                         VARCHAR(128)  NOT NULL,
    event_type                           VARCHAR(64)   NOT NULL,
    payload                              TEXT         ,
    status                               CHAR(1)       NOT NULL DEFAULT 'P',
    attempts                             INTEGER       NOT NULL DEFAULT 0,
    available_at                         TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    lease_until                          TIMESTAMP    ,
    lease_token                          BIGINT       ,
    last_error                           TEXT         ,
    created_at                           TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at                           TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT outbox_event_pk PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS idx_outbox_drain ON outbox_event(status, available_at);
CREATE INDEX IF NOT EXISTS idx_outbox_aggregate ON outbox_event(aggregate_type, aggregate_id);

CREATE SEQUENCE IF NOT EXISTS outbox_event_seq INCREMENT BY 1 START WITH 1;
INSERT INTO table_sequence_usage (table_name, column_name, sequence_name) VALUES ('outbox_event', 'id', 'outbox_event_seq') ON CONFLICT DO NOTHING;

-- Catalog of runtime configuration flags loaded into common.BaseConfig at startup. Non-secret values only; store a secret NAME here, never secret material.
CREATE TABLE IF NOT EXISTS application_config_flag (
    id                                   VARCHAR(80)   NOT NULL,
    data_type                            VARCHAR(20)   NOT NULL DEFAULT 'string',
    needs_restart                        BOOLEAN       NOT NULL DEFAULT FALSE,
    default_value                        TEXT         ,
    description                          TEXT         ,
    CONSTRAINT application_config_flag_pk PRIMARY KEY (id)
);

-- Per-node assigned values for application_config_flag. node_id identifies the runtime node/process (matched against --node_id). Most single-node deployments use 0; multi-node deployments assign values per node. Missing rows fall back to application_config_flag.default_value.
CREATE TABLE IF NOT EXISTS application_config_value (
    node_id                              INTEGER       NOT NULL DEFAULT 0,
    flag_id                              VARCHAR(80)   NOT NULL,
    assigned_value                       TEXT         ,
    CONSTRAINT application_config_value_pk PRIMARY KEY (node_id, flag_id)
);

-- Agency capability and approval state for a business partner. Referral
-- commission is available to every approved agency; wholesale_allowed is a
-- permission for per-client wholesale assignments, not a global billing mode.
CREATE TABLE IF NOT EXISTS agency_profile (
    agency_partner_id                    BIGINT        NOT NULL,
    wholesale_allowed                    BOOLEAN       NOT NULL DEFAULT FALSE,
    default_commission_rate_bp           INTEGER      ,
    approved_at                          TIMESTAMP    ,
    suspended                            BOOLEAN       NOT NULL DEFAULT FALSE,
    created_at                           TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at                           TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT agency_profile_pk PRIMARY KEY (agency_partner_id),
    CONSTRAINT chk_agency_profile_rate CHECK (default_commission_rate_bp IS NULL OR (default_commission_rate_bp > 0 AND default_commission_rate_bp <= 10000))
);

-- An agency's staged and invited prospective clients. Prospects need not be
-- users or partners yet; client_partner_id is populated only after the
-- invitee has a partner and explicitly accepts the delegation.
CREATE TABLE IF NOT EXISTS agency_client_invitation (
    id                                   BIGINT        NOT NULL,
    agency_partner_id                    BIGINT        NOT NULL,
    client_name                          VARCHAR(200)  NOT NULL,
    client_email                         VARCHAR(255) ,
    client_website                       VARCHAR(255) ,
    invite_token                         VARCHAR(64)  ,
    status                               CHAR(1)       NOT NULL DEFAULT 'S',
    client_partner_id                    BIGINT       ,
    accepted_by                          BIGINT       ,
    invited_at                           TIMESTAMP    ,
    accepted_at                          TIMESTAMP    ,
    created_at                           TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at                           TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT agency_client_invitation_pk PRIMARY KEY (id)
);
CREATE UNIQUE INDEX IF NOT EXISTS invitation_token_uq ON agency_client_invitation(invite_token);
CREATE INDEX IF NOT EXISTS idx_agency_client_invitation ON agency_client_invitation(agency_partner_id, status);

CREATE SEQUENCE IF NOT EXISTS agency_client_invitation_seq INCREMENT BY 1 START WITH 1;
INSERT INTO table_sequence_usage (table_name, column_name, sequence_name) VALUES ('agency_client_invitation', 'id', 'agency_client_invitation_seq') ON CONFLICT DO NOTHING;

-- Owner-granted, revocable partner-to-partner management delegation. The
-- generic table permits several active rows for one client partner so an app
-- extension can scope them to different managed entities (for example, each
-- business). The direct-partner base service enforces one active row itself.
CREATE TABLE IF NOT EXISTS agency_client_delegation (
    id                                   BIGINT        NOT NULL,
    client_partner_id                    BIGINT        NOT NULL,
    agency_partner_id                    BIGINT        NOT NULL,
    granted_by                           BIGINT        NOT NULL,
    status                               CHAR(1)       NOT NULL DEFAULT 'A',
    granted_at                           TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    revoked_at                           TIMESTAMP    ,
    revoked_by                           BIGINT       ,
    CONSTRAINT agency_client_delegation_pk PRIMARY KEY (id),
    CONSTRAINT chk_delegation_distinct CHECK (client_partner_id <> agency_partner_id),
    CONSTRAINT chk_delegation_lifecycle CHECK ((status = 'A' AND revoked_at IS NULL AND revoked_by IS NULL) OR (status = 'R' AND revoked_at IS NOT NULL AND revoked_by IS NOT NULL))
);
CREATE UNIQUE INDEX IF NOT EXISTS delegation_episode_uq ON agency_client_delegation(agency_partner_id, client_partner_id, granted_at);
CREATE INDEX IF NOT EXISTS idx_agency_client_delegation_client ON agency_client_delegation(client_partner_id, status);
CREATE INDEX IF NOT EXISTS idx_agency_client_delegation_agency ON agency_client_delegation(agency_partner_id, status);

CREATE SEQUENCE IF NOT EXISTS agency_client_delegation_seq INCREMENT BY 1 START WITH 1;
INSERT INTO table_sequence_usage (table_name, column_name, sequence_name) VALUES ('agency_client_delegation', 'id', 'agency_client_delegation_seq') ON CONFLICT DO NOTHING;

-- Effective-dated referral (R) or wholesale (W) model per delegation. The
-- partial unique index permits only one open row without a database extension;
-- services close then insert atomically and validate historical intervals.
CREATE TABLE IF NOT EXISTS agency_client_billing (
    id                                   BIGINT        NOT NULL,
    client_delegation_id                 BIGINT        NOT NULL,
    billing_model                        CHAR(1)       NOT NULL,
    effective_from                       TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    effective_to                         TIMESTAMP    ,
    created_at                           TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT agency_client_billing_pk PRIMARY KEY (id),
    CONSTRAINT chk_agency_client_billing_model CHECK (billing_model IN ('R', 'W')),
    CONSTRAINT chk_agency_client_billing_period CHECK (effective_to IS NULL OR effective_to > effective_from)
);
CREATE UNIQUE INDEX IF NOT EXISTS agency_client_billing_open_uq ON agency_client_billing(client_delegation_id) WHERE effective_to IS NULL;
CREATE INDEX IF NOT EXISTS idx_agency_client_billing_period ON agency_client_billing(client_delegation_id, effective_from);

CREATE SEQUENCE IF NOT EXISTS agency_client_billing_seq INCREMENT BY 1 START WITH 1;
INSERT INTO table_sequence_usage (table_name, column_name, sequence_name) VALUES ('agency_client_billing', 'id', 'agency_client_billing_seq') ON CONFLICT DO NOTHING;

-- Selects the exact active user_bank_info version used for an agency's
-- commission payouts. The composite FK proves the destination belongs to the
-- agency; user and provider are derived from user_bank_info, not duplicated.
CREATE TABLE IF NOT EXISTS agency_payout_profile (
    agency_partner_id                    BIGINT        NOT NULL,
    user_bank_info_id                    BIGINT        NOT NULL,
    status                               CHAR(1)       NOT NULL DEFAULT 'A',
    created_at                           TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at                           TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT agency_payout_profile_pk PRIMARY KEY (agency_partner_id),
    CONSTRAINT chk_agency_payout_profile_status CHECK (status IN ('A', 'I'))
);

-- Percentage commission rate frozen per agency/client at the client's first
-- earning. Resolution prefers agency_profile.default_commission_rate_bp and
-- otherwise uses application_config_value/default_commission_rate_bp.
CREATE TABLE IF NOT EXISTS agency_client_rate (
    agency_partner_id                    BIGINT        NOT NULL,
    client_partner_id                    BIGINT        NOT NULL,
    commission_rate_bp                   INTEGER       NOT NULL,
    first_earned_at                      TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT agency_client_rate_pk PRIMARY KEY (agency_partner_id, client_partner_id),
    CONSTRAINT chk_agency_client_rate CHECK (commission_rate_bp > 0 AND commission_rate_bp <= 10000)
);

-- Append-only earning/reversal ledger. The frozen percentage is snapshotted
-- in applied_rate_bp; only payout lifecycle status changes after insertion.
-- Codes are column-scoped: entry_type E=earning/R=reversal; status H=held,
-- P=payable, R=reserved, D=disbursed, O=offset/settled reversal.
CREATE TABLE IF NOT EXISTS agency_commission (
    id                                   BIGINT        NOT NULL,
    client_billing_id                    BIGINT        NOT NULL,
    invoice_line_payment_id              BIGINT        NOT NULL,
    earning_period_start                 TIMESTAMP     NOT NULL,
    earning_period_end                   TIMESTAMP     NOT NULL,
    gross_amount_minor                   BIGINT        NOT NULL,
    commission_amount_minor              BIGINT        NOT NULL,
    applied_rate_bp                      INTEGER       NOT NULL,
    currency                             CHAR(3)       NOT NULL,
    entry_type                           CHAR(1)       NOT NULL,
    status                               CHAR(1)       NOT NULL DEFAULT 'H',
    reversal_of_id                       BIGINT       ,
    created_at                           TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    earned_at                            TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT agency_commission_pk PRIMARY KEY (id),
    CONSTRAINT chk_agency_commission_entry CHECK ((entry_type = 'E' AND gross_amount_minor > 0 AND commission_amount_minor > 0 AND reversal_of_id IS NULL) OR (entry_type = 'R' AND gross_amount_minor < 0 AND commission_amount_minor < 0 AND reversal_of_id IS NOT NULL)),
    CONSTRAINT chk_agency_commission_period CHECK (earning_period_end > earning_period_start),
    CONSTRAINT chk_agency_commission_rate CHECK (applied_rate_bp > 0 AND applied_rate_bp <= 10000)
);
CREATE UNIQUE INDEX IF NOT EXISTS agency_commission_source_uq ON agency_commission(invoice_line_payment_id, earning_period_start) WHERE entry_type = 'E';
CREATE INDEX IF NOT EXISTS idx_agency_commission_status ON agency_commission(status, currency);
CREATE INDEX IF NOT EXISTS idx_agency_commission_billing ON agency_commission(client_billing_id);

CREATE SEQUENCE IF NOT EXISTS agency_commission_seq INCREMENT BY 1 START WITH 1;
INSERT INTO table_sequence_usage (table_name, column_name, sequence_name) VALUES ('agency_commission', 'id', 'agency_commission_seq') ON CONFLICT DO NOTHING;

-- One aggregate payout per agency, currency, destination, and selection
-- cutoff. Destination fields are immutable snapshots. user_id is derived
-- through user_bank_info and is deliberately not duplicated here. Status:
-- C=created, P=provider-pending, D=disbursed, F=failed, M=manual review,
-- R=returned, V=reversed. Codes are scoped to this column.
CREATE TABLE IF NOT EXISTS agency_payout (
    id                                   BIGINT        NOT NULL,
    agency_partner_id                    BIGINT        NOT NULL,
    user_bank_info_id                    BIGINT        NOT NULL,
    amount_minor                         BIGINT        NOT NULL,
    currency                             CHAR(3)       NOT NULL,
    provider                             CHAR(2)       NOT NULL,
    provider_account_id                  VARCHAR(100)  NOT NULL,
    selection_cutoff_at                  TIMESTAMP     NOT NULL,
    idempotency_key                      VARCHAR(100)  NOT NULL,
    provider_transfer_id                 VARCHAR(255) ,
    provider_funding_id                  VARCHAR(255) ,
    status                               CHAR(1)       NOT NULL DEFAULT 'C',
    attempt_count                        INTEGER       NOT NULL DEFAULT 0,
    attempted_at                         TIMESTAMP    ,
    next_attempt_at                      TIMESTAMP    ,
    paid_at                              TIMESTAMP    ,
    failure_message                      TEXT         ,
    created_at                           TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT agency_payout_pk PRIMARY KEY (id),
    CONSTRAINT chk_agency_payout_amount CHECK (amount_minor > 0)
);
CREATE UNIQUE INDEX IF NOT EXISTS agency_payout_idem_uq ON agency_payout(idempotency_key);
CREATE UNIQUE INDEX IF NOT EXISTS agency_payout_transfer_uq ON agency_payout(provider, provider_transfer_id) WHERE provider_transfer_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_agency_payout_funding ON agency_payout(provider_funding_id) WHERE provider_funding_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS agency_payout_cycle_uq ON agency_payout(agency_partner_id, currency, provider_account_id, selection_cutoff_at) WHERE status <> 'F';

CREATE SEQUENCE IF NOT EXISTS agency_payout_seq INCREMENT BY 1 START WITH 1;
INSERT INTO table_sequence_usage (table_name, column_name, sequence_name) VALUES ('agency_payout', 'id', 'agency_payout_seq') ON CONFLICT DO NOTHING;

-- Allocation of commission ledger entries to aggregate payouts. A null
-- released_at marks the live allocation; terminal failure releases the line.
CREATE TABLE IF NOT EXISTS agency_payout_line (
    payout_id                            BIGINT        NOT NULL,
    commission_id                        BIGINT        NOT NULL,
    amount_minor                         BIGINT        NOT NULL,
    released_at                          TIMESTAMP    ,
    CONSTRAINT agency_payout_line_pk PRIMARY KEY (payout_id, commission_id),
    CONSTRAINT chk_agency_payout_line_amount CHECK (amount_minor <> 0)
);
CREATE UNIQUE INDEX IF NOT EXISTS agency_payout_line_live_uq ON agency_payout_line(commission_id) WHERE released_at IS NULL;

